<script setup lang="ts">import {airports} from '~/data/site'</script>
<template><div class="interior-page"><SeoSetup title="UK Airports | VIP Meet & Greet & Airport Assistance" description="Explore VIP airport assistance enquiries for Heathrow, Gatwick, Manchester, Edinburgh, Birmingham and Stansted." path="/airports"/><div style="background:#071a2a"><SiteHeader/></div><section class="interior-hero"><div class="shell"><span class="eyebrow">EXPLORE OUR DESTINATIONS</span><h1>UK airports, exceptional journeys.</h1><p>Find airport-specific meet and assist options for international arrivals, departures and transfers. Service availability is confirmed individually.</p></div></section><main class="interior-body shell"><div class="wide-card-grid"><NuxtLink v-for="a in airports" :key="a.slug" :to="`/airports/${a.slug}`" class="simple-card"><img :src="a.image" :alt="`${a.name} travel`" loading="lazy"/><div><span class="eyebrow">{{a.code}} · {{a.location}}</span><h2>{{a.name}}</h2><p>{{a.description}}</p><span class="text-link">Explore airport ↗</span></div></NuxtLink></div></main><SiteFooter/></div></template>
